const fs = await import('node:fs/promises');
const P2 = "D:\\GitHub\\My-second-brain\\50-知识\\AI工具";
// 验证书签文件格式
const bm = await fs.readFile(P2+"\\接单平台书签-70个.html","utf8");
const anchors = (bm.match(/<DT><A HREF=/g)||[]).length;
const folders = (bm.match(/<DT><H3 /g)||[]).length;
const valid = bm.startsWith("<!DOCTYPE NETSCAPE-Bookmark-file-1>") && bm.trim().endsWith("</DL><p>");
const sample = bm.split("\n").slice(6,12).join("\n");
return { anchors, folders, valid, sample };
